@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // Disable CSRF for REST APIs
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll() // Open endpoints
                .requestMatchers("/api/admin/**").hasRole("ADMIN") // Admin only
                .anyRequest().authenticated() // All others need auth
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS) // No HTTP sessions for REST
            )
            .httpBasic(Customizer.withDefaults()) // Enable HTTP Basic auth
            .build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(); // Required for password hashing
    }
}

@Configuration
@EnableWebSecurity
@EnableMethodSecurity // Enables @PreAuthorize
public class RestSecurityConfig {

    @Bean
    public SecurityFilterChain restApiFilterChain(HttpSecurity http, JwtAuthenticationFilter jwtFilter) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // No CSRF for REST APIs
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS) // No HTTP sessions
            )
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/auth/login", "/auth/register").permitAll() // Public endpoints
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated() // All other endpoints require auth
            )
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class) // JWT validation
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint((req, res, authEx) -> {
                    res.setStatus(HttpServletResponse.SC_UNAUTHORIZED); // Return JSON 401
                    res.setContentType("application/json");
                    res.getWriter().write("{\"error\":\"Unauthorized\"}");
                })
            )
            .build();
    }
}

@Component
public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {
    @Override
    public void commence(HttpServletRequest request, HttpServletResponse response, 
                         AuthenticationException authException) throws IOException {
        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED); // 401
        response.setContentType("application/json");
        var errorResponse = Map.of(
            "error", "Unauthorized",
            "message", authException.getMessage(),
            "path", request.getRequestURI()
        );
        response.getWriter().write(new ObjectMapper().writeValueAsString(errorResponse));
    }
}

@Component
public class RestAccessDeniedHandler implements AccessDeniedHandler {
    @Override
    public void handle(HttpServletRequest request, HttpServletResponse response, 
                       AccessDeniedException accessDeniedException) throws IOException {
        response.setStatus(HttpServletResponse.SC_FORBIDDEN); // 403
        response.setContentType("application/json");
        var errorResponse = Map.of(
            "error", "Forbidden",
            "message", "Access denied",
            "path", request.getRequestURI()
        );
        response.getWriter().write(new ObjectMapper().writeValueAsString(errorResponse));
    }
}

@Configuration
@EnableWebSecurity
@EnableMethodSecurity // For @PreAuthorize
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http, JwtAuthenticationFilter jwtFilter) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // Q: Why disable CSRF? A: REST uses tokens, not cookies
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS) // Q: Why STATELESS? A: JWT per request, no sessions
            )
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/auth/**").permitAll() // Public login endpoints
                .requestMatchers("/api/admin/**").hasRole("ADMIN") // Role-based URL security
                .anyRequest().authenticated() // Q: Default deny — all others need auth
            )
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class) // JWT validation filter
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint((req, res, e) -> res.sendError(401, "Unauthorized")) // Q: 401 vs 403?
            )
            .build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(); // Q: Why BCrypt? A: Slow hashing resists brute-force
    }
}
